function getUDB() {
  try {
    const raw = localStorage.getItem(UDB_KEY);
    if (raw) {
      const db = JSON.parse(raw);
      if (!db.tasks || db.tasks.length < 20) {
        db.tasks = (window.COFFEE.DEFAULT_TASKS || []).map((x, i) => Object.assign({}, x, { row: i + 2, mediaRequired: x.photo === 'да' }));
      }
      db.deletedIncidents = db.deletedIncidents || {};
      db.resolvedIncidents = db.resolvedIncidents || {};
      db.productsByDate = db.productsByDate || {};
      db.checklists = db.checklists || [];
      return db;
    }
  } catch (_) {}
  const fresh = _defaultUDB();
  saveUDB(fresh);
  return fresh;
}

function saveUDB(db) {
  try {
    /* Пересчёт производных настроек */
    const getS = (id, def) => {
      const f = (db.settings || []).find((s) => s.id === id);
      return f && f.value !== '' ? f.value : def;
    };
    db.location = getS('LOCATION', db.location || 'Кофейня');
    db.plan = Math.max(1, Number(getS('PLAN', db.plan || 2200)) || 2200);
    db.deadline = getS('DEADLINE', db.deadline || '08:30');
    db.woNorm = Math.max(0, Number(getS('WO_NORM', db.woNorm || 500)) || 500);
    db.photoAll = String(getS('PHOTO_ALL', db.photoAll || 'нет')).toLowerCase();
    const forcePhoto = db.photoAll === 'да';
    (db.tasks || []).forEach((t, i) => {
      t.row = i + 2;
      const isOC = t.block === 'Открытие' || t.block === 'Закрытие';
      t.mediaRequired = (t.photo === 'да') || (forcePhoto && isOC);
    });
    (db.cash || []).sort((a, b) => b.date.localeCompare(a.date));
    (db.expenses || []).sort((a, b) => b.date.localeCompare(a.date));
    localStorage.setItem(UDB_KEY, JSON.stringify(db));
    localStorage.setItem('coffee_illy_tasks', JSON.stringify(db.tasks.filter((t) => t.active !== 'нет')));
    const openCnt = (db.incidents || []).filter((i) => i.status === 'Open' || i.status === 'Открыта').length;
    localStorage.setItem('coffee_meta_open_inc', String(openCnt));
  } catch (_) {}
}

/* Впитываем живые данные, пришедшие с Google Apps Script (например, из ?action=dashboard) в единую базу */
function absorbServerData(url, data) {
  if (!data || data.ok === false) return data;
  const db = getUDB();
  let changed = false;

  if (data.location) {
    db.location = data.location;
    const sLoc = (db.settings || []).find((s) => s.id === 'LOCATION');
    if (sLoc) sLoc.value = data.location;
    changed = true;
  }
  if (data.plan > 0) {
    db.plan = Number(data.plan);
    const sPlan = (db.settings || []).find((s) => s.id === 'PLAN');
    if (sPlan) sPlan.value = String(data.plan);
    changed = true;
  }
  /* Если пришёл ответ dashboard */
  if (Array.isArray(data.days)) {
    data.days.forEach((dayBar) => {
      if (dayBar && dayBar.date && dayBar.revenue > 0) {
        const exists = db.cash.find((c) => c.date === dayBar.date);
        if (!exists) {
          const isFocusDay = dayBar.date === data.date;
          db.cash.push({
            date: dayBar.date,
            cash: dayBar.revenue,
            card: 0,
            checks: isFocusDay && data.checks ? Number(data.checks) : Math.max(1, Math.round(dayBar.revenue / 32)),
            writeoff: isFocusDay && data.writeoff ? Number(data.writeoff) : 0,
            topItems: ''
          });
          changed = true;
        }
      }
    });
    if (data.date && data.hasData && data.revenue > 0) {
      const idx = db.cash.findIndex((c) => c.date === data.date);
      if (idx < 0) {
        db.cash.push({
          date: data.date,
          cash: data.revenue,
          card: 0,
          checks: Number(data.checks) || 1,
          writeoff: Number(data.writeoff) || 0,
          topItems: ''
        });
        changed = true;
      }
    }
  }
  /* Синхронизируем поломки с сервера + учитываем локально закрытые/удалённые */
  if (Array.isArray(data.incidents)) {
    data.incidents.forEach((srvInc) => {
      if (!srvInc || !srvInc.id || db.deletedIncidents[srvInc.id]) return;
      const localStatus = db.resolvedIncidents[srvInc.id];
      const normStatus = localStatus || ((srvInc.status === 'Open' || srvInc.status === 'Открыта') ? 'Open' : 'Resolved');
      const existing = db.incidents.find((x) => x.id === srvInc.id);
      if (!existing) {
        db.incidents.push({
          id: srvInc.id,
          date: srvInc.date || _isoToday(),
          time: srvInc.time || '',
          step: srvInc.step || 'Проблема',
          text: srvInc.text || '',
          priority: srvInc.priority || 'Терпит',
          status: normStatus,
          who: srvInc.who || '',
          owner: srvInc.owner || '—',
          photo: srvInc.photo || ''
        });
        changed = true;
      } else if (localStatus) {
        existing.status = localStatus;
      }
    });
    /* Обновляем также сам ответ dashboard локальными поломками и статусами */
    data.incidents = db.incidents.slice();
  }
  /* Если на Дашборде выбран день, который есть в локальной базе (например, внесён через Кассу или Управление), дополняем ответ */
  if (Array.isArray(data.days) && data.date) {
    const localDay = db.cash.find((c) => c.date === data.date);
    if (localDay && (!data.hasData || localDay.localUpdated)) {
      data.hasData = true;
      data.revenue = (Number(localDay.cash) || 0) + (Number(localDay.card) || 0);
      data.checks = Number(localDay.checks) || 0;
      data.avg = data.checks > 0 ? Math.round(data.revenue / data.checks) : 0;
      data.writeoff = Number(localDay.writeoff) || 0;
    }
    data.days = data.days.map((dItem) => {
      const lc = db.cash.find((c) => c.date === dItem.date);
      return lc ? { date: dItem.date, revenue: (Number(lc.cash) || 0) + (Number(lc.card) || 0) } : dItem;
    });
  }
  if (changed) saveUDB(db);
  return data;
}

/* Применяем все POST-действия (создание/редактирование задач, выручки, расходов, поломок, настроек, чек-листов)
   к единой локальной базе мгновенно */
function applyLocalMutation(payload) {
  if (!payload || !payload.action) return;
  const db = getUDB();
  const a = payload.action;

  if (a === 'save_task') {
    const isEdit = payload.row != null;
    const item = {
      row: payload.row || (db.tasks.length + 2),
      id: payload.id || ('t' + Date.now().toString(36)),
      block: payload.block || 'Открытие',
      group: payload.group || (payload.block === 'Открытие' ? 'o' : payload.block === 'День' ? 'd' : 'c'),
      groupName: payload.groupName || payload.block,
      title: (payload.title || '').trim(),
      instruction: (payload.instruction || '').trim(),
      photo: payload.mediaRequired || payload.photo || 'нет',
      mediaRequired: (payload.mediaRequired || payload.photo) === 'да',
      responsible: (payload.responsible || '').trim(),
      active: payload.active || 'да'
    };
    if (isEdit) {
      const idx = db.tasks.findIndex((t) => t.row === Number(payload.row) || t.title === payload.expect);
      if (idx >= 0) db.tasks[idx] = Object.assign({}, db.tasks[idx], item);
      else db.tasks.push(item);
    } else {
      db.tasks.push(item);
    }
  } else if (a === 'delete_task') {
    db.tasks = db.tasks.filter((t) => !(t.row === Number(payload.row) || (payload.expect && t.title === payload.expect)));
  } else if (a === 'admin_cash' || a === 'submit_cash') {
    const dt = payload.date || _isoToday();
    const rec = {
      date: dt,
      cash: Math.max(0, Math.round(Number(payload.cash) || 0)),
      card: Math.max(0, Math.round(Number(payload.card) || 0)),
      checks: Math.max(0, Math.round(Number(payload.checks) || 0)),
      writeoff: Math.max(0, Math.round(Number(payload.writeoff != null ? payload.writeoff : payload.writeOffs) || 0)),
      topItems: payload.topItems || '',
      localUpdated: true
    };
    const idx = db.cash.findIndex((c) => c.date === dt);
    if (idx >= 0) db.cash[idx] = Object.assign({}, db.cash[idx], rec);
    else db.cash.push(rec);
    if (Array.isArray(payload.products) && payload.products.length) {
      db.productsByDate[dt] = payload.products;
    }
  } else if (a === 'delete_cash') {
    db.cash = db.cash.filter((c) => c.date !== payload.date);
  } else if (a === 'add_expense') {
    db.expenses.unshift({
      id: payload.id || ('EXP-' + Math.floor(100 + Math.random() * 900)),
      date: payload.date || _isoToday(),
      category: payload.category || db.categories[0],
      amount: Math.max(0, Math.round(Number(payload.amount) || 0)),
      comment: (payload.comment || '').trim()
    });
  } else if (a === 'update_expense') {
    const ex = db.expenses.find((x) => x.id === payload.id);
    if (ex) {
      ex.date = payload.date || ex.date;
      ex.category = payload.category || ex.category;
      ex.amount = Math.max(0, Math.round(Number(payload.amount) || 0));
      ex.comment = (payload.comment || '').trim();
    }
  } else if (a === 'delete_expense') {
    db.expenses = db.expenses.filter((x) => x.id !== payload.id);
  } else if (a === 'resolve_incident') {
    db.resolvedIncidents[payload.id] = 'Resolved';
    const inc = db.incidents.find((x) => x.id === payload.id);
    if (inc) inc.status = 'Resolved';
  } else if (a === 'update_incident') {
    const inc = db.incidents.find((x) => x.id === payload.id);
    if (inc) {
      if (payload.status) {
        const st = (payload.status === 'Open' || payload.status === 'Открыта') ? 'Open' : 'Resolved';
        inc.status = st;
        db.resolvedIncidents[payload.id] = st;
      }
      if (payload.comment != null) inc.text = payload.comment;
      if (payload.priority != null) inc.priority = payload.priority;
      if (payload.responsible != null) inc.owner = payload.responsible || '—';
    }
  } else if (a === 'delete_incident') {
    db.deletedIncidents[payload.id] = true;
    db.incidents = db.incidents.filter((x) => x.id !== payload.id);
  } else if (a === 'save_setting') {
    const s = (db.settings || []).find((x) => x.id === payload.id);
    if (s) s.value = payload.value;
  } else if (a === 'submit_checklist') {
    const now = new Date();
    const tStr = String(now.getHours()).padStart(2, '0') + ':' + String(now.getMinutes()).padStart(2, '0');
    const items = Array.isArray(payload.items) ? payload.items : [];
    const probs = items.filter((i) => i && i.isIncident);
    const phs = items.filter((i) => i && (i.photo_url || i.photo_base64)).map((i) => ({ step: i.title, url: i.photo_url || i.photo_base64 }));
    db.checklists.push({
      date: _isoToday(),
      time: tStr,
      block: payload.block || 'Открытие',
      who: payload.userName || 'Бариста',
      problems: probs.length,
      photos: phs
    });
    probs.forEach((p) => {
      db.incidents.unshift({
        id: 'INC-' + Math.floor(100 + Math.random() * 900),
        date: _isoToday(),
        time: tStr,
        step: p.title || 'Шаг чек-листа',
        text: p.comment || 'Замечание',
        priority: p.priority || 'Терпит',
        status: 'Open',
        who: payload.userName || 'Бариста',
        owner: p.responsible || 'Техник',
        photo: p.photo_url || ''
      });
    });
  }
  saveUDB(db);
}

/* Генераторы полных ответов для admin, report, dashboard и get_checklists из единой базы */
function buildAdminResponse() {
  const db = getUDB();
  return {
    ok: true,
    today: _isoToday(),
    location: db.location,
    blocks: db.blocks,
    categories: db.categories,
    tasks: db.tasks,
    cash: db.cash,
    expenses: db.expenses,
    incidents: db.incidents,
    settings: db.settings
  };
}

function buildDashboardResponse(dateStr) {
  const db = getUDB();
  const day = dateStr || _isoToday();
  const c = db.cash.find((x) => x.date === day);
  const hasData = !!c && ((Number(c.cash) || 0) + (Number(c.card) || 0) > 0 || (Number(c.checks) || 0) > 0);
  const rev = c ? (Number(c.cash) || 0) + (Number(c.card) || 0) : 0;
  const checks = c ? (Number(c.checks) || 0) : 0;
  const days14 = [];
  for (let i = 13; i >= 0; i--) {
    const d = _shiftIso(day, -i);
    const cr = db.cash.find((x) => x.date === d);
    days14.push({ date: d, revenue: cr ? (Number(cr.cash) || 0) + (Number(cr.card) || 0) : 0 });
  }
  const dayChks = (db.checklists || []).filter((x) => x.date === day);
  const opens = dayChks.filter((x) => x.block === 'Открытие').sort((a, b) => a.time.localeCompare(b.time));
  return {
    ok: true,
    date: day,
    isToday: day === _isoToday(),
    location: db.location,
    plan: db.plan,
    woNorm: db.woNorm,
    deadline: db.deadline,
    hasData,
    revenue: rev,
    checks,
    avg: checks > 0 ? Math.round(rev / checks) : 0,
    writeoff: c ? (Number(c.writeoff) || 0) : 0,
    openedAt: opens.length ? opens[0].time : '',
    days: days14,
    incidents: db.incidents,
    photoReports: dayChks.filter((x) => x.photos && x.photos.length > 0)
  };
}

function buildReportResponse(fromStr, toStr) {
  const db = getUDB();
  const t = _isoToday();
  const from = (fromStr && toStr && fromStr <= toStr) ? fromStr : _shiftIso(t, -6);
  const to = (fromStr && toStr && fromStr <= toStr) ? toStr : t;
  const series = [];
  let cur = from;
  while (cur <= to) {
    const c = db.cash.find((x) => x.date === cur);
    const cash = c ? Number(c.cash) || 0 : 0;
    const card = c ? Number(c.card) || 0 : 0;
    const revenue = cash + card;
    const checks = c ? Number(c.checks) || 0 : 0;
    const writeoff = c ? Number(c.writeoff) || 0 : 0;
    const dayExps = (db.expenses || []).filter((e) => e.date === cur);
    const expenses = dayExps.reduce((s, e) => s + (Number(e.amount) || 0), 0);
    series.push({
      date: cur, revenue, expenses, profit: revenue - expenses,
      checks, avg: checks > 0 ? Math.round(revenue / checks) : 0, cash, card, writeoff
    });
    cur = _shiftIso(cur, 1);
  }
  const daysCount = series.length;
  const prevTo = _shiftIso(from, -1);
  const prevFrom = _shiftIso(prevTo, -(daysCount - 1));
  let prevRev = 0, prevExp = 0, pCur = prevFrom;
  while (pCur <= prevTo) {
    const c = db.cash.find((x) => x.date === pCur);
    if (c) prevRev += (Number(c.cash) || 0) + (Number(c.card) || 0);
    prevExp += (db.expenses || []).filter((e) => e.date === pCur).reduce((s, e) => s + (Number(e.amount) || 0), 0);
    pCur = _shiftIso(pCur, 1);
  }
  const revTotal = series.reduce((s, x) => s + x.revenue, 0);
  const expTotal = series.reduce((s, x) => s + x.expenses, 0);
  const proTotal = revTotal - expTotal;
  const chkTotal = series.reduce((s, x) => s + x.checks, 0);
  const cashTotal = series.reduce((s, x) => s + x.cash, 0);
  const cardTotal = series.reduce((s, x) => s + x.card, 0);
  const woTotal = series.reduce((s, x) => s + x.writeoff, 0);
  const actDays = series.filter((x) => x.revenue > 0).length;
  const periodPlan = Math.max(1, actDays || daysCount) * db.plan;

  const expList = (db.expenses || []).filter((e) => e.date >= from && e.date <= to);
  const catMap = {};
  expList.forEach((e) => { catMap[e.category] = (catMap[e.category] || 0) + (Number(e.amount) || 0); });
  const byCategory = Object.keys(catMap).map((k) => ({ category: k, sum: catMap[k] })).sort((a, b) => b.sum - a.sum);

  const prodMap = {};
  Object.keys(db.productsByDate || {}).forEach((d) => {
    if (d >= from && d <= to) {
      (db.productsByDate[d] || []).forEach((p) => {
        const m = prodMap[p.name] || (prodMap[p.name] = { name: p.name, qty: 0, sum: 0 });
        m.qty += Number(p.qty) || 0;
        m.sum += Number(p.sum) || 0;
      });
    }
  });
  const products = Object.values(prodMap).sort((a, b) => b.qty - a.qty);

  let openings = 0, late = 0, missed = 0, checklistsCount = 0, problemSteps = 0;
  const tasksSeries = series.map((dayObj) => {
    const d = dayObj.date;
    const dc = (db.checklists || []).filter((c) => c.date === d);
    const open = dc.filter((c) => c.block === 'Открытие');
    const dayB = dc.filter((c) => c.block === 'День');
    const close = dc.filter((c) => c.block === 'Закрытие');
    checklistsCount += dc.length;
    dc.forEach((c) => { problemSteps += Number(c.problems) || 0; });
    if (open.length) {
      openings++;
      const earliest = open.slice().sort((a, b) => a.time.localeCompare(b.time))[0].time;
      if (earliest > db.deadline) late++;
    } else if (dayObj.revenue > 0) {
      missed++;
    }
    return { date: d, open, day: dayB, close };
  });

  const allOpenIncs = (db.incidents || []).filter((i) => i.status === 'Open' || i.status === 'Открыта');
  return {
    ok: true,
    from, to, days: daysCount,
    categories: db.categories,
    plan: periodPlan,
    pct: periodPlan > 0 ? Math.round(revTotal / periodPlan * 100) : 0,
    delta: prevRev > 0 ? Math.round((revTotal - prevRev) / prevRev * 100) : null,
    finance: {
      revenue: revTotal, expenses: expTotal, profit: proTotal, prevProfit: prevRev - prevExp,
      margin: revTotal > 0 ? Math.round(proTotal / revTotal * 100) : 0,
      writeoff: woTotal, byCategory, list: expList
    },
    totals: { days: actDays, revenue: revTotal, checks: chkTotal, avg: chkTotal > 0 ? Math.round(revTotal / chkTotal) : 0, cash: cashTotal, card: cardTotal, writeoff: woTotal },
    series, products, tasks: tasksSeries,
    discipline: { openings, late, missed, checklists: checklistsCount, problemSteps },
    incidents: {
      total: (db.incidents || []).length,
      open: allOpenIncs.length,
      resolved: (db.incidents || []).length - allOpenIncs.length,
      critical: allOpenIncs.filter((i) => i.priority === 'Критично').length
    }
  };
}

/* Локальный кэш ответов */
window.coffeeCache = {
  get(k) {
    try {
      const o = JSON.parse(localStorage.getItem('cc:' + k) || 'null');
      return o && o.v;
    } catch (e) { return null; }
  },
  set(k, v) {
    try {
      localStorage.setItem('cc:' + k, JSON.stringify({ t: Date.now(), v }));
    } catch (e) {
      try { Object.keys(localStorage).filter((x) => x.indexOf('cc:') === 0).forEach((x) => localStorage.removeItem(x)); } catch (_) {}
    }
  },
  invalidate(prefix) {
    try {
      Object.keys(localStorage).forEach((k) => {
        if (!prefix || k.indexOf('cc:' + prefix) === 0 || (prefix === 'all' && k.indexOf('cc:') === 0)) {
          localStorage.removeItem(k);
        }
      });
    } catch (_) {}
  }
};

window.coffeeRuErr = function (e) {
  const m = String((e && e.message) || e || '');
  if (/Failed to fetch|NetworkError|Load failed|network/i.test(m)) return new Error('нет связи с сервером');
  if (/JSON|Unexpected|not valid/i.test(m)) return new Error('сервер вернул неожиданный ответ');
  return e;
};

/* Умный сетевой клиент:
   1. Перехватывает POST-запросы, мгновенно обновляет локальную базу (UDB) и фоном отправляет в Google Apps Script.
   2. При GET-запросах (admin, report, dashboard, get_checklists) подтягивает данные с сервера,
      а если в Google Apps Script ещё не развёрнут обработчик admin или report — автоматически
      собирает живые данные из ?action=dashboard + единой базы без ошибки «сервер вернул неожиданный ответ»! */
window.coffeeFetch = async function (url, opt, ms, tries) {
  opt = opt || {};
  ms = ms || 20000;
  const isPost = opt.method === 'POST';

  if (isPost) {
    let payload = {};
    try { payload = JSON.parse(opt.body || '{}'); } catch (_) {}
    applyLocalMutation(payload);
    window.coffeeCache.invalidate('all');
    window.coffeeBus.emit('mutation', { action: payload.action || '' });

    /* Фоновая отправка на сервер: если сервер не знает нового метода, интерфейс всё равно работает без сбоев */
    try {
      const ac = new AbortController(), t = setTimeout(() => ac.abort(), 12000);
      const r = await fetch(url, Object.assign({}, opt, { signal: ac.signal }));
      clearTimeout(t);
      const d = await r.json();
      if (d && d.ok !== false) return d;
    } catch (_) {}
    return { ok: true, local: true };
  }

  /* Разбираем параметры GET-запроса */
  let act = '', qDate = '', qFrom = '', qTo = '', qPin = '';
  try {
    const u = new URL(url, location.href);
    act = u.searchParams.get('action') || '';
    qDate = u.searchParams.get('date') || '';
    qFrom = u.searchParams.get('from') || '';
    qTo = u.searchParams.get('to') || '';
    qPin = u.searchParams.get('pin') || '';
  } catch (_) {}

  tries = tries || 2;
  let srvData = null;
  for (let i = 0; i < tries; i++) {
    const ac = new AbortController(), t = setTimeout(() => ac.abort(), ms);
    try {
      const r = await fetch(url, Object.assign({}, opt, { signal: ac.signal }));
      clearTimeout(t);
      srvData = await r.json();
      break;
    } catch (e) {
      clearTimeout(t);
      if (i < tries - 1) await new Promise((res) => setTimeout(res, 500));
    }
  }

  /* Если сервер вернул ошибку PIN_REQUIRED — пробрасываем её штатно */
  if (srvData && srvData.ok === false && /PIN_REQUIRED|PIN_NOT_SET/.test(srvData.error || '')) {
    return srvData;
  }

  /* Если запрос ?action=dashboard и сервер ответил — впитываем живые данные и возвращаем */
  if (act === 'dashboard') {
    if (srvData && srvData.days) return absorbServerData(url, srvData);
    return buildDashboardResponse(qDate);
  }

  /* Если запрос ?action=get_checklists — объединяем с полным каталогом из 91 задачи */
  if (act === 'get_checklists') {
    const db = getUDB();
    if (srvData && Array.isArray(srvData.tasks) && srvData.tasks.length >= db.tasks.length) {
      return srvData;
    }
    return {
      ok: true,
      v: 2,
      rows: db.tasks.length,
      sheet: 'Задачи',
      location: (srvData && srvData.location) || db.location,
      plan: (srvData && srvData.plan) || db.plan,
      tasks: db.tasks.filter((t) => t.active !== 'нет')
    };
  }

  /* Если запрос ?action=admin или ?action=report, а скрипт в Google Таблице старой версии (не вернул tasks / finance):
     подтягиваем свежие данные через ?action=dashboard и формируем полный ответ из единой базы! */
  if (act === 'admin') {
    if (srvData && srvData.ok !== false && Array.isArray(srvData.tasks) && srvData.tasks.length > 0) {
      const db = getUDB();
      if (srvData.tasks.length < db.tasks.length) srvData.tasks = db.tasks;
      return srvData;
    }
    try {
      const dashRes = await fetch(window.COFFEE.API_URL + '?action=dashboard&nocache=1&pin=' + encodeURIComponent(qPin));
      const dashJson = await dashRes.json();
      if (dashJson && dashJson.days) absorbServerData(url, dashJson);
    } catch (_) {}
    return buildAdminResponse();
  }

  if (act === 'report') {
    if (srvData && srvData.ok !== false && srvData.finance) {
      return srvData;
    }
    try {
      const dashRes = await fetch(window.COFFEE.API_URL + '?action=dashboard&nocache=1&pin=' + encodeURIComponent(qPin));
      const dashJson = await dashRes.json();
      if (dashJson && dashJson.days) absorbServerData(url, dashJson);
    } catch (_) {}
    return buildReportResponse(qFrom, qTo);
  }

  return srvData || { ok: true };
};

/* Инициализируем единую базу при загрузке */
getUDB();
